/**
 * The contract `switch-field.tsx` (native) and `switch-field.web.tsx` (DOM) both implement. Its own
 * module because Metro resolves `./switch-field` to `switch-field.web.tsx` on web — the web file
 * would otherwise import itself.
 */
export type SwitchFieldProps = {
  /** The switch's id. On web it is also what the caption's `<label htmlFor>` points at. */
  id: string;
  label: string;
  /**
   * A line under the caption: what the switch does, or why it cannot be changed. On web it is the
   * switch's description (`aria-describedby`), so the reason a switch is disabled is read with it.
   */
  description?: string | undefined;
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
  /** The switch cannot be changed, and the caption is muted. `description` is where to say why. */
  disabled?: boolean | undefined;
  className?: string | undefined;
  labelClassName?: string | undefined;
};

/** The caption's type, shared so the two halves cannot drift on it. */
export const SWITCH_FIELD_LABEL_CLASS = "text-sm text-foreground/60";

/** The line under it. Not muted with the caption: it is what explains a disabled switch. */
export const SWITCH_FIELD_DESCRIPTION_CLASS = "font-normal text-foreground/60 text-xs";

/** The ids the caption and the description carry, from the switch's own. */
export const switchFieldIds = (id: string) => ({
  labelId: `${id}-label`,
  descriptionId: `${id}-description`,
});

/**
 * Copied from `registry/ui/switch-field.web.tsx` by `scripts/rn2web`.
 * Do not edit — edit the source and re-run `npm run compile`.
 *
 * This is level 4 of the plan: the item has a hand-written web half, so nothing was generated. The
 * same passes still ran over it, and for a file already written against the DOM they find nothing
 * to do beyond pointing its sibling imports at the web tree. That is deliberate — running one
 * pipeline over the whole output tree is what guarantees a hand-written half and a compiled one
 * speak the same prop vocabulary, instead of the two drifting where nobody is looking.
 */

/**
 * The web switch field: one `<label htmlFor>` wrapping the switch and its caption, so the whole row
 * is the switch's hit target and the switch is the row's only tab stop. `switch-field.tsx` is the
 * native counterpart and `switch-field-base.ts` holds the contract they share.
 *
 * It used to be compiled from the native source, whose caption is a `Pressable` that toggles the
 * switch by hand. That compiled to a `<button>` around the `<label htmlFor>`, and a click on the
 * caption then toggled twice — the button's handler, then the label's activation clicking the
 * switch — and so did nothing. It also put a second, role-less tab stop after the switch, and a
 * label inside a button is not valid HTML. The label alone is the whole mechanism here: a click on
 * the switch itself is a click on interactive content, which a label does not re-activate.
 */

import {
  SWITCH_FIELD_DESCRIPTION_CLASS,
  SWITCH_FIELD_LABEL_CLASS,
  type SwitchFieldProps,
  switchFieldIds,
} from "@/components/ui/switch-field-base";
import { cn } from "@/lib/utils";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";

/** A switch with its caption on one row, where pressing the caption toggles it. */
export function SwitchField({
  id,
  label,
  description,
  checked,
  onCheckedChange,
  disabled,
  className,
  labelClassName,
}: SwitchFieldProps) {
  const { labelId, descriptionId } = switchFieldIds(id);
  const caption = cn(SWITCH_FIELD_LABEL_CLASS, disabled && "opacity-50", labelClassName);
  return (
    <Label
      htmlFor={id}
      data-slot="switch-field"
      className={cn(
        "flex flex-row gap-2",
        description ? "items-start" : "items-center",
        disabled ? "cursor-not-allowed" : "cursor-pointer",
        className,
      )}
    >
      <Switch
        id={id}
        checked={checked}
        onCheckedChange={onCheckedChange}
        disabled={disabled}
        // The description sits inside the `<label>` so the whole row stays the hit target, and a
        // label names its control with everything in it. Naming the switch by the caption alone
        // keeps the description out of the name and leaves it to be the description.
        aria-labelledby={description ? labelId : undefined}
        aria-describedby={description ? descriptionId : undefined}
      />
      {description ? (
        <span className="flex min-w-0 flex-col gap-0.5">
          <span id={labelId} className={caption}>
            {label}
          </span>
          <span id={descriptionId} className={SWITCH_FIELD_DESCRIPTION_CLASS}>
            {description}
          </span>
        </span>
      ) : (
        <span className={caption}>{label}</span>
      )}
    </Label>
  );
}

export type { SwitchFieldProps };
